package org.securemail.ui;
import java.util.*;import com.google.gson.GsonBuilder;
public final class SharedRuntimeOriginProbe { public static void main(String[] args)throws Exception { Map<String,String> origins=new LinkedHashMap<>();for(String name:List.of("org.securemail.ui.ThemeManager","org.securemail.ui.MessengerApp","org.securemail.ui.InWindowDialog","org.securemail.ui.InWindowFileChooser","org.securemail.ui.AppearanceGallery","org.securemail.ui.AppearanceView","org.securemail.ui.InterfaceFailureMessages","org.securemail.ui.ArchiveView","org.securemail.client.storage.LocalStore","org.securemail.client.archive.EncryptedArchive","org.securemail.protocol.Algorithm")){Class<?> type=Class.forName(name,false,SharedRuntimeOriginProbe.class.getClassLoader());origins.put(name,type.getProtectionDomain().getCodeSource().getLocation().toString());}System.out.println(new GsonBuilder().setPrettyPrinting().create().toJson(origins));}}
